#!/usr/bin/env bash
# Differential test: Go port vs. the Rust reference, on shared random cases.
# Usage: scripts/difftest.sh /path/to/rust-ref-binary [cases.tsv]
# Without cases.tsv the cases are generated by scripts/gen_cases.py.
# The Rust binary must read the same tab-separated protocol as internal/difftest.
set -euo pipefail
RUST_BIN=${1:?rust reference binary}; CASES=${2:-}
if [ -z "$CASES" ]; then CASES=$(mktemp); python3 scripts/gen_cases.py > "$CASES"; fi
go build -o /tmp/omwei-gohar ./internal/difftest
"$RUST_BIN" < "$CASES" > /tmp/omwei-rust.out
/tmp/omwei-gohar < "$CASES" > /tmp/omwei-go.out
cmp /tmp/omwei-rust.out /tmp/omwei-go.out && echo "IDENTICAL ($(wc -l < "$CASES") cases)"
